    if !valid_rect(rect) {
        return Err(LayoutError::InvalidGeometry);
    }
    let size = self.members[&window].size(Size {
        width: rect.width,
        height: rect.height,
    });
    rect.width = size.width;
    rect.height = size.height;
    if !bounded_rect(rect) {
