1489	    fn spatial_neighbor(
1490	        &self,
1491	        window: WindowId,
1492	        direction: Direction,
1493	        floats_only: bool,
1494	    ) -> Option<WindowId> {
1495	        let placements = self.projected_placements();
1496	        let source = placements.iter().find(|p| p.window == window).unwrap().rect;
1497	        let origin = center(source);
1498	        placements
1499	            .iter()
1500	            .filter(|p| {
1501	                p.window != window && p.visible && (!floats_only || self.is_floating(p.window))
1502	            })
1503	            .filter_map(|candidate| {
1504	                let r = candidate.rect;
1505	                let p = center(r);
1506	                let (forward, perpendicular, edge) = match direction {
1507	                    Direction::Left => (
1508	                        origin.x - p.x,
1509	                        (origin.y - p.y).abs(),
1510	                        source.x - (r.x + r.width),
1511	                    ),
1512	                    Direction::Right => (
1513	                        p.x - origin.x,
1514	                        (origin.y - p.y).abs(),
