    fn new_toplevel(&mut self, surface: ToplevelSurface) {
        self.add_toplevel(surface);
    }

    fn ack_configure(&mut self, surface: WlSurface, _configure: Configure) {
        // Smithay has already accepted this serial and retired its predecessors.
        // State requests can arrive before the first buffer. The helper's
        // initial_configure_sent check prevents a stale post-unmap ack from
        // starting the next mapping cycle prematurely.
        if let Some(item) = self.window_id(&surface).and_then(|id| self.windows.get(id))
            && let Some(toplevel) = item.window.toplevel()
        {
            crate::configure::send_pending(toplevel);
        }
        self.bump_sequence();
    }

    fn new_popup(&mut self, surface: PopupSurface, _positioner: PositionerState) {
        // Creating a fresh popup after its root left the scene must not recreate
        // a tree that was dismissed by an earlier unmap/hide transaction.
        let visible = find_popup_root_surface(&PopupKind::Xdg(surface.clone()))
            .is_ok_and(|root| self.popup_root_visible(&root));
        if !visible {
            surface.send_popup_done();
            return;
        }
        self.unconstrain_popup(&surface);
        let _ = self.popups.track_popup(PopupKind::Xdg(surface));
    }

    fn reposition_request(
        &mut self,
        surface: PopupSurface,
        positioner: PositionerState,
        token: u32,
    ) {
        surface.with_pending_state(|state| {
            let geometry = positioner.get_geometry();
            state.geometry = geometry;
            state.positioner = positioner;
        });
        self.unconstrain_popup(&surface);
        surface.send_repositioned(token);
    }

    fn move_request(&mut self, surface: ToplevelSurface, seat: wl_seat::WlSeat, serial: Serial) {
        let Some(seat) = Seat::from_resource(&seat) else {
            return;
        };
        if seat != self.seat
            || self
                .seat
                .get_keyboard()
                .is_some_and(|keyboard| keyboard.is_grabbed())
            || !seat
                .get_pointer()
                .and_then(|pointer| {
                    pointer
                        .with_grab(|_, grab| grab.is::<smithay::input::pointer::ClickGrab<Self>>())
                })
                .unwrap_or(false)
            || !self
                .pointer_presses
                .values()
                .any(|pressed| *pressed == serial)
        {
            return;
        }
        let wl_surface = surface.wl_surface();
        let Some(start_data) = check_grab(&seat, wl_surface, serial) else {
            return;
        };
        let Some(pointer) = seat.get_pointer() else {
            return;
        };
        let Some(id) = self.window_id(wl_surface) else {
            return;
        };
        if !crate::grabs::move_grab::floating_role_live(self, id, wl_surface) {
            return;
        }
        let Some(initial_rect) = self.layout.floating_rect(id) else {
            return;
        };
        let grab = MoveSurfaceGrab {
            start_data,
            window_id: id,
            surface: wl_surface.clone(),
            initial_rect,
            initial_zoom: self.layout.camera().zoom,
        };
        pointer.set_grab(self, grab, serial, Focus::Clear);
    }

    fn resize_request(
        &mut self,
        surface: ToplevelSurface,
        seat: wl_seat::WlSeat,
        serial: Serial,
        edges: xdg_toplevel::ResizeEdge,
    ) {
        let Some(edges) = crate::grabs::resize_grab::ResizeEdge::from_protocol(edges) else {
            return;
        };
        let Some(seat) = Seat::from_resource(&seat) else {
            return;
        };
        if seat != self.seat
            || self
                .seat
                .get_keyboard()
                .is_some_and(|keyboard| keyboard.is_grabbed())
            || !seat
                .get_pointer()
                .and_then(|pointer| {
                    pointer
                        .with_grab(|_, grab| grab.is::<smithay::input::pointer::ClickGrab<Self>>())
                })
                .unwrap_or(false)
            || !self
                .pointer_presses
                .values()
                .any(|pressed| *pressed == serial)
        {
            return;
        }
        let wl_surface = surface.wl_surface();
        let Some(start_data) = check_grab(&seat, wl_surface, serial) else {
            return;
        };
        let Some(pointer) = seat.get_pointer() else {
            return;
        };
        let Some(id) = self.window_id(wl_surface) else {
            return;
        };
        if !crate::grabs::move_grab::floating_role_live(self, id, wl_surface) {
            return;
        }
        let Some(initial_rect) = self.layout.floating_rect(id) else {
            return;
        };
        surface.with_pending_state(|state| {
            state.states.set(xdg_toplevel::State::Resizing);
        });
        crate::configure::send_pending(&surface);
        let grab = ResizeSurfaceGrab::start(
            start_data,
            id,
            wl_surface.clone(),
            edges,
            initial_rect,
            self.layout.camera().zoom,
        );
        pointer.set_grab(self, grab, serial, Focus::Clear);
    }

    fn grab(&mut self, surface: PopupSurface, seat: wl_seat::WlSeat, serial: Serial) {
        self.cleanup_popup_grab();
        let Some(seat) = Seat::from_resource(&seat) else {
            surface.send_popup_done();
            return;
        };
        // Only an active same-client pointer press authorizes a new popup grab.
        // Keyboard/touch initiated grabs remain unsupported until their input
        // serial provenance is tracked explicitly.
        if !self
            .pointer_presses
            .values()
            .any(|pressed| *pressed == serial)
        {
            self.stats.popup_grabs_denied_missing_press = self
                .stats
                .popup_grabs_denied_missing_press
                .saturating_add(1);
            surface.send_popup_done();
            return;
        }
        if check_grab(&seat, surface.wl_surface(), serial).is_none() {
            surface.send_popup_done();
            return;
        }
        let kind = PopupKind::Xdg(surface.clone());
        let Ok(root) = find_popup_root_surface(&kind) else {
            surface.send_popup_done();
            return;
        };
        let Some(id) = self.window_id(&root) else {
            surface.send_popup_done();
            return;
        };
        if !self.popup_root_visible(&root) {
            surface.send_popup_done();
            return;
        }
        let Ok(mut grab) = self.popups.grab_popup(root, kind, &seat, serial) else {
            surface.send_popup_done();
            return;
        };
        self.popup_grab = Some((id, grab.clone()));
        if let Some(keyboard) = seat.get_keyboard() {
            if keyboard.is_grabbed()
                && !(keyboard.has_grab(serial)
                    || keyboard.has_grab(grab.previous_serial().unwrap_or(serial)))
            {
                grab.ungrab(PopupUngrabStrategy::All);
                return;
            }
            keyboard.set_focus(self, grab.current_grab(), serial);
            keyboard.set_grab(self, PopupKeyboardGrab::new(&grab), serial);
        }
        if let Some(pointer) = seat.get_pointer() {
            if pointer.is_grabbed()
                && !(pointer.has_grab(serial)
                    || pointer.has_grab(grab.previous_serial().unwrap_or_else(|| grab.serial())))
            {
                grab.ungrab(PopupUngrabStrategy::All);
                return;
            }
            pointer.set_grab(self, PopupPointerGrab::new(&grab), serial, Focus::Keep);
        }
    }

    fn fullscreen_request(
        &mut self,
        surface: ToplevelSurface,
        _output: Option<smithay::reexports::wayland_server::protocol::wl_output::WlOutput>,
    ) {
        // One eligible output exists; stale/foreign preferences fall back to it.
        crate::configure::defer_reply(&surface);
        if let Some(id) = self.window_id(surface.wl_surface())
            && let Err(error) = self.set_window_fullscreen(id, true)
        {
            tracing::debug!(%id,%error,"fullscreen request declined");
        }
        crate::configure::send_pending(&surface);
    }
    fn unfullscreen_request(&mut self, surface: ToplevelSurface) {
        crate::configure::defer_reply(&surface);
        if let Some(id) = self.window_id(surface.wl_surface())
            && let Err(error) = self.set_window_fullscreen(id, false)
        {
            tracing::debug!(%id,%error,"unfullscreen request declined");
        }
        crate::configure::send_pending(&surface);
    }

    fn maximize_request(&mut self, surface: ToplevelSurface) {
        crate::configure::defer_reply(&surface);
        if let Some(id) = self.window_id(surface.wl_surface())
            && let Err(error) = self.set_window_maximized(id, true)
        {
            tracing::debug!(%id, %error, "maximize request declined");
        }
        crate::configure::send_pending(&surface);
    }
    fn unmaximize_request(&mut self, surface: ToplevelSurface) {
        crate::configure::defer_reply(&surface);
        if let Some(id) = self.window_id(surface.wl_surface())
            && let Err(error) = self.set_window_maximized(id, false)
        {
            tracing::debug!(%id, %error, "unmaximize request declined");
        }
        crate::configure::send_pending(&surface);
    }

    fn minimize_request(&mut self, surface: ToplevelSurface) {
        if let Some(id) = self.window_id(surface.wl_surface())
            && let Err(error) = self.set_window_minimized(id, true)
        {
            tracing::debug!(%id, %error, "minimize request declined");
        }
    }

    fn app_id_changed(&mut self, _surface: ToplevelSurface) {
        self.bump_sequence();
    }

    fn title_changed(&mut self, _surface: ToplevelSurface) {
        self.bump_sequence();
    }

    fn toplevel_destroyed(&mut self, surface: ToplevelSurface) {
        self.remove_toplevel(surface.wl_surface());
    }

    fn popup_destroyed(&mut self, _surface: PopupSurface) {
        self.popups.cleanup();
        self.cleanup_popup_grab();
        self.request_redraw();
    }
}

fn check_grab(
    seat: &Seat<Fluxwm>,
    surface: &WlSurface,
    serial: Serial,
) -> Option<PointerGrabStartData<Fluxwm>> {
    let pointer = seat.get_pointer()?;

    // Check that this surface has a click grab.
    if !pointer.has_grab(serial) {
        return None;
    }

    let start_data = pointer.grab_start_data()?;

    let (focus, _) = start_data.focus.as_ref()?;
    // If the focus was for a different surface, ignore the request.
    if !focus.id().same_client_as(&surface.id()) {
        return None;
    }

    Some(start_data)
}

/// Should be called on `WlSurface::commit`
pub fn handle_commit(state: &mut Fluxwm, surface: &WlSurface, just_unmapped: bool) {
    if let Some(id) = state.window_id(surface) {
        let initial = with_states(surface, |states| {
            states
                .data_map
                .get::<XdgToplevelSurfaceData>()
                .is_some_and(|data| !data.lock().unwrap().initial_configure_sent)
        });
        // A null-buffer unmap is not the initial bufferless commit of the
        // next mapping cycle. Wait for that subsequent commit before configuring.
        if initial
            && !just_unmapped
            && let Some(toplevel) = state
                .windows
                .get(id)
                .and_then(|item| item.window.toplevel())
        {
            crate::configure::clear_reply(toplevel);
            toplevel.send_configure();
        }
    }

