    .filter(|(_, item)| !item.window.alive())
    .map(|(id, _)| id)
    .collect();
for id in dead {
    if let Some(surface) = self
        .windows
        .get(id)
        .and_then(|item| item.window.toplevel())
        .map(|toplevel| toplevel.wl_surface().clone())
    {
        Self::dismiss_root_popups(&surface);
    }
    if let Some(item) = self.windows.remove(id) {
        self.cancel_window_grab(id);
        self.space.unmap_elem(&item.window);
        if item.mapped {
            let _ = self.layout.remove(id);
        }
        self.stats.destroyed += 1;
        self.bump_sequence();
        self.relayout();
        self.restore_keyboard_focus();
    }
}
if !self.stopping
    && self.shutdown_deadline.is_none()
    && !self.seat.get_keyboard().is_some_and(|k| k.is_grabbed())
    && !self.seat.get_pointer().is_some_and(|p| p.is_grabbed())
{
    let pending: Vec<_> = self
        .windows
        .iter()
        .filter_map(|(id, item)| item.minimize_pending.then_some(id))
        .collect();
    for id in pending {
        self.windows
            .get_mut(id)
            .expect("retained role")
            .minimize_pending = false;
        self.bump_sequence();
        if let Err(error) = self.set_window_minimized(id, true) {
            tracing::debug!(%id, %error, "deferred minimize declined");
        }
    }
}
self.reap_children();
self.space.refresh();
self.popups.cleanup();
self.cleanup_popup_grab();
if std::mem::take(&mut self.health_requested) || self.shutdown_deadline.is_some() {
    match self
        .health
        .poll(std::time::Instant::now(), self.shutdown_deadline.is_some())
    {
        Ok(true) => self.bump_sequence(),
        Ok(false) => (),
        Err(error) => self.fail(format!("shell health timer: {error}")),
    }
}
self.drive_ipc();
self.cleanup_popup_grab();
self.drive_config();
self.drive_autostart();
self.refresh_pointer_focus();
self.flush_wayland();

